public class Main {public static void main(String[]args){Complex a=new Complex(1,2),b=new Complex(3,-4);for(Complex x:new Complex[]{a.add(b),a.subtract(b),a.multiply(b),a.divide(b),Complex.sum(new Complex[]{new Complex(1,1),new Complex(1,-1)}),Complex.product(new Complex[]{new Complex(1,1),new Complex(1,-1)})})System.out.println(x.real()+" + "+x.imaginary()+"i");System.out.println("Пустое произведение: "+Complex.product(new Complex[0]).real());}}
